type Props = {
  params: Promise<{ slug: string }>
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params
  const query = `*[_type == "post" && slug.current == $slug][0] { title, description }`

  let post: { title: string; description: string } | null = null
  try {
    post = await client.fetch(query, { slug })
  } catch (error) {
    console.error("Metadata fetch failed", error)
  }

  // Fallback title logic for demo
  if (!post) {
    const fallbackTitles: Record<string, string> = {
      'xay-dung-cau-truc-phap-ly': 'Xây Dựng Cấu Trúc Pháp Lý Ngay Từ Ngày Đầu',
      'tam-chien-binh-nhu-nuoc': 'Tâm Chiến Binh Như Nước: Linh Hoạt, Phản Chiếu',
      'go-to-market-aggressive': 'Chiến Lược Chiếm Lĩnh Thị Trường',
      'hieu-phong-cach-truong-phai': 'Hiểu Phong Cách Các Trường Phái Khác',
      'biet-cai-co-de-thay-cai-khong': 'Biết Cái Có Để Thấy Cái Không',
    }

    return {
      title: `${fallbackTitles[slug] || 'Chân Kinh'} | Chân Kinh Online`,
      description: 'Sacred Knowledge Archive',
    }
  }

  return {
    title: `${post.title} | Chân Kinh Online`,
    description: post.description,
  }
}

